package com.elogistic.backend.identity.internal.web;
import com.elogistic.backend.identity.api.*;
import com.elogistic.backend.identity.internal.application.port.*;
import com.elogistic.backend.identity.internal.infrastructure.JdbcIdentityRateLimiter;
import java.util.*;
import java.time.*;
import java.security.*;
import java.security.interfaces.*;
import org.junit.jupiter.api.*;
import org.springframework.mock.web.*;
import jakarta.servlet.http.Cookie;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
class ProductionAuthenticationHttpTests {
    private static final Instant NOW=Instant.parse("2026-10-24T00:05:00Z");private static final UUID ID=UUID.randomUUID(),SID=UUID.randomUUID(),RID=UUID.randomUUID();
    private static KeyPair key;private IdentitySessionCommands sessions;private IdentityBrowserState browser;private IdentityRateLimiter limiter;private ProductionSessionAdmission admission;private ProductionAuthenticationHttp http;
    private static final String C="c".repeat(43),T="t".repeat(43),R="r".repeat(43),ORIGIN="https://portal.example.invalid";
    @BeforeAll static void keys()throws Exception{var g=KeyPairGenerator.getInstance("RSA");g.initialize(3072);key=g.generateKeyPair();}
    @BeforeEach void setup(){
        sessions=mock(IdentitySessionCommands.class);browser=mock(IdentityBrowserState.class);limiter=mock(IdentityRateLimiter.class);admission=new ProductionSessionAdmission(browser,limiter);
        var tokens=new ProductionAccessTokens("https://identity.example.invalid","browser","test",(RSAPrivateKey)key.getPrivate(),Map.of("test",(RSAPublicKey)key.getPublic()),Clock.fixed(NOW,ZoneOffset.UTC));
        when(browser.issue(any(),any())).thenReturn(new IdentityBrowserState.Challenge(C,T));when(browser.rebind(any(),any())).thenReturn(new IdentityBrowserState.Challenge(C,T));
        when(limiter.reserve(any())).thenReturn(success->{});when(sessions.loginIdentity(any())).thenAnswer(i->result());when(sessions.refreshIdentity(any())).thenAnswer(i->result());
        http=new ProductionAuthenticationHttp(sessions,admission,browser,limiter,tokens,ORIGIN,Clock.fixed(NOW,ZoneOffset.UTC));
    }
    private IdentitySessionCommands.Result result(){return new IdentitySessionCommands.Result(new IdentitySessionCommands.AccessGrant(SID,ID,1,NOW,NOW.plusSeconds(900)),new IdentityGrantCommands.Account(ID,"synthetic","Synthetic","fixture@example.invalid","ACTIVE",List.of(),1,true),NOW.plusSeconds(28800),R.getBytes(java.nio.charset.StandardCharsets.US_ASCII));}
    private MockHttpServletRequest request(String route){var r=new MockHttpServletRequest(route.equals("csrf")?"GET":"POST","/api/v1/auth/"+route);r.setSecure(true);r.addHeader("Origin",ORIGIN);r.addHeader("X-CSRF-Token",T);r.setCookies(new Cookie("__Host-elogistics.csrf",C),new Cookie("__Host-elogistics.refresh",R));r.setContentType("application/json");if(route.equals("login"))r.setContent("{\"username\":\"synthetic\",\"password\":\"legacy\"}".getBytes(java.nio.charset.StandardCharsets.UTF_8));return r;}
    private MockHttpServletResponse run(MockHttpServletRequest r)throws Exception{var s=new MockHttpServletResponse();s.setHeader("X-Request-Id",RID.toString());s.setHeader("Cache-Control","no-store");http.handle(r,s);return s;}
    private void code(MockHttpServletResponse s,int status,String code)throws Exception{assertEquals(status,s.getStatus());assertEquals(code,new tools.jackson.databind.ObjectMapper().readTree(s.getContentAsString()).get("code").asString());assertEquals(RID.toString(),s.getHeader("X-Request-Id"));assertEquals("no-store",s.getHeader("Cache-Control"));assertFalse(s.getContentAsString().contains("legacy"));}
    private void assertSecureCookie(String header,boolean logout){
        var cookie=org.springframework.mock.web.MockCookie.parse(header);
        assertEquals("/",cookie.getPath());assertNull(cookie.getDomain());assertEquals(true,cookie.getSecure());assertEquals(true,cookie.isHttpOnly());assertEquals("Strict",cookie.getAttribute("SameSite"));
        assertEquals(true,Set.of("__Host-elogistics.csrf","__Host-elogistics.refresh").contains(cookie.getName()));
        if(cookie.getName().equals("__Host-elogistics.csrf")){assertEquals(C,cookie.getValue());assertEquals(900,cookie.getMaxAge());}
        else {assertEquals(logout?"":R,cookie.getValue());assertEquals(logout?0:28800,cookie.getMaxAge());}
    }
    @Test void csrfUsesOnlyChallengeAndSecureCookie()throws Exception{var s=run(request("csrf"));assertEquals(200,s.getStatus());assertEquals(T,new tools.jackson.databind.ObjectMapper().readTree(s.getContentAsString()).get("csrfToken").asString());assertEquals(1,s.getHeaders("Set-Cookie").size());verifyNoInteractions(sessions,limiter);}
    @Test void loginIssuesAcceptedAccessBodyAndTwoHostOnlyCookies()throws Exception{var s=run(request("login"));assertEquals(200,s.getStatus());var n=new tools.jackson.databind.ObjectMapper().readTree(s.getContentAsString());assertEquals(5,n.size());assertEquals("Bearer",n.get("tokenType").asString());assertEquals(900,n.get("expiresIn").asInt());assertEquals(2,s.getHeaders("Set-Cookie").size());for(String cookie:s.getHeaders("Set-Cookie")){assertSecureCookie(cookie,false);}assertFalse(s.getContentAsString().contains(R));}
    @Test void insecureTransportCannotBeUpgradedByForwardedHeaders()throws Exception{var r=request("login");r.setSecure(false);r.addHeader("X-Forwarded-Proto","https");code(run(r),403,"ORIGIN_REJECTED");verifyNoInteractions(sessions,limiter);}
    @Test void missingPostOriginRejectedBeforeCredentials()throws Exception{var r=request("login");r.removeHeader("Origin");code(run(r),403,"ORIGIN_REJECTED");verifyNoInteractions(sessions);}
    @Test void crossOriginAndDuplicateOriginsRejected()throws Exception{for(String origin:List.of("null","https://evil.example.invalid")){var r=request("refresh");r.removeHeader("Origin");r.addHeader("Origin",origin);code(run(r),403,"ORIGIN_REJECTED");}var r=request("logout");r.addHeader("Origin",ORIGIN);code(run(r),403,"ORIGIN_REJECTED");}
    @Test void csrfGetWithoutOriginIsSameOriginReadableOnly()throws Exception{var r=request("csrf");r.removeHeader("Origin");assertEquals(200,run(r).getStatus());}
    @Test void missingAndDuplicateCsrfHeadersReject()throws Exception{var r=request("login");r.removeHeader("X-CSRF-Token");code(run(r),403,"CSRF_REJECTED");r=request("login");r.addHeader("X-CSRF-Token",T);code(run(r),403,"CSRF_REJECTED");verifyNoInteractions(sessions);}
    @Test void duplicateCookiesCannotSelectAnAlternativeCredential()throws Exception{var r=request("login");r.setCookies(new Cookie("__Host-elogistics.csrf",C),new Cookie("__Host-elogistics.csrf",T));code(run(r),403,"CSRF_REJECTED");verifyNoInteractions(sessions);}
    @Test void csrfStoreDenialPreventsQuotaAndAuthentication()throws Exception{doThrow(new IdentityCommandFailure(IdentityCommandFailure.Code.CSRF_REJECTED)).when(browser).verify(any(),any(),any(),anyBoolean());code(run(request("login")),403,"CSRF_REJECTED");verifyNoInteractions(sessions,limiter);}
    @Test void invalidJsonAndUnknownFieldsHaveSafeValidationError()throws Exception{for(String body:List.of("{","{\"username\":\"x\",\"password\":\"legacy\",\"actor\":\"self\"}","{\"username\":\"a\",\"username\":\"b\",\"password\":\"legacy\"}")){var r=request("login");r.setContent(body.getBytes());code(run(r),400,"VALIDATION_FAILED");}verifyNoInteractions(sessions,limiter);}
    @Test void loginDoesNotNormalizeUsernameOrPassword()throws Exception{var r=request("login");r.setContent("{\"username\":\" Case \",\"password\":\" secret \"}".getBytes());assertEquals(200,run(r).getStatus());var c=org.mockito.ArgumentCaptor.forClass(IdentitySessionCommands.Login.class);verify(sessions).loginIdentity(c.capture());assertEquals(" Case ",c.getValue().username());assertEquals(" secret ",c.getValue().password());}
    @Test void oversizeAndWrongMediaTypeRejectedBeforeAuthentication()throws Exception{var r=request("login");r.setContent(new byte[16385]);code(run(r),400,"VALIDATION_FAILED");r=request("login");r.setContentType("text/plain");code(run(r),400,"VALIDATION_FAILED");verifyNoInteractions(sessions);}
    @Test void invalidCredentialsFinalizeOnlyFailedAccountReservation()throws Exception{var reservation=mock(IdentityRateLimiter.Reservation.class);when(limiter.reserve(any())).thenReturn(reservation);when(sessions.loginIdentity(any())).thenThrow(new IdentityCommandFailure(IdentityCommandFailure.Code.INVALID_CREDENTIALS));code(run(request("login")),401,"INVALID_CREDENTIALS");verify(reservation).finishLogin(false);verify(reservation,never()).finishLogin(true);}
    @Test void successfulLoginReleasesOnlyItsOwnAccountReservation()throws Exception{var reservation=mock(IdentityRateLimiter.Reservation.class);when(limiter.reserve(any())).thenReturn(reservation);assertEquals(200,run(request("login")).getStatus());verify(reservation).finishLogin(true);}
    @Test void exhaustedQuotaIs429WithRetryAfter()throws Exception{when(limiter.reserve(any())).thenThrow(new IdentityRateLimiter.Exhausted(72));var s=run(request("login"));code(s,429,"RATE_LIMITED");assertEquals("72",s.getHeader("Retry-After"));verifyNoInteractions(sessions);}
    @Test void unavailableQuotaIs503Never429OrAuthentication()throws Exception{when(limiter.reserve(any())).thenThrow(new IdentityRateLimiter.Unavailable());var s=run(request("login"));code(s,503,"SERVICE_UNAVAILABLE");assertNull(s.getHeader("Retry-After"));assertTrue(s.getHeaders("Set-Cookie").isEmpty());verifyNoInteractions(sessions);}
    @Test void finalizationFailureNeverPublishesCredentials()throws Exception{var reservation=mock(IdentityRateLimiter.Reservation.class);when(limiter.reserve(any())).thenReturn(reservation);doThrow(new IdentityRateLimiter.Unavailable()).when(reservation).finishLogin(true);var s=run(request("login"));code(s,503,"SERVICE_UNAVAILABLE");assertTrue(s.getHeaders("Set-Cookie").isEmpty());assertFalse(s.getContentAsString().contains("accessToken"));}
    @Test void refreshReplacesCookieWithoutRebindingCsrfOrIdle()throws Exception{var s=run(request("refresh"));assertEquals(200,s.getStatus());assertEquals(2,s.getHeaders("Set-Cookie").size());verify(browser,never()).rebind(any(),any());verify(sessions).refreshIdentity(any());}
    @Test void refreshReplayHasStable401WithoutSuccessCookies()throws Exception{when(sessions.refreshIdentity(any())).thenThrow(new IdentityCommandFailure(IdentityCommandFailure.Code.REFRESH_REPLAY));var s=run(request("refresh"));code(s,401,"REFRESH_REPLAY");assertTrue(s.getHeaders("Set-Cookie").isEmpty());}
    @Test void logoutClearsRefreshOnlyAfterConfirmedRevocation()throws Exception{var s=run(request("logout"));assertEquals(204,s.getStatus());assertEquals("",s.getContentAsString());for(String header:s.getHeaders("Set-Cookie"))assertSecureCookie(header,true);assertEquals(2,s.getHeaders("Set-Cookie").size());verify(sessions).logoutIdentity(any());verifyNoInteractions(limiter);}
    @Test void failedLogoutIs503WithoutClaimingRevocation()throws Exception{doThrow(new IllegalStateException("SYNTHETIC_DATABASE_ERROR")).when(sessions).logoutIdentity(any());var s=run(request("logout"));code(s,503,"SERVICE_UNAVAILABLE");assertTrue(s.getHeaders("Set-Cookie").isEmpty());assertFalse(s.getContentAsString().contains("DATABASE"));}
    @Test void csrfStorageFailureIs503()throws Exception{when(browser.issue(any(),any())).thenThrow(new IdentityRateLimiter.Unavailable());code(run(request("csrf")),503,"SERVICE_UNAVAILABLE");}
    @Test void admissionWithoutVerifiedScopeFailsClosed(){assertThrows(IdentityCommandFailure.class,()->admission.authorize(SessionAdmission.Operation.LOGIN,RID,null,false));}
    @Test void admissionChecksRequestAndFamilyBeforeRefreshQuota()throws Exception{try(var scope=admission.enter(RID,C,T)){assertThrows(IdentityCommandFailure.class,()->admission.authorize(SessionAdmission.Operation.REFRESH,UUID.randomUUID(),SID,true));admission.authorize(SessionAdmission.Operation.REFRESH,RID,SID,true);verify(browser).verify(C,T,SID,false);verify(limiter).reserve(List.of(new IdentityRateLimiter.Subject(IdentityRateLimiter.Policy.REFRESH_SESSION,SID.toString())));}assertThrows(IdentityCommandFailure.class,()->admission.authorize(SessionAdmission.Operation.LOGOUT,RID,null,false));}
    @Test void forwardedIpCannotChangeLimiterSubject()throws Exception{var r=request("login");r.setRemoteAddr("192.0.2.10");r.addHeader("X-Forwarded-For","198.51.100.99");assertEquals(200,run(r).getStatus());verify(limiter).reserve(List.of(new IdentityRateLimiter.Subject(IdentityRateLimiter.Policy.LOGIN_ACCOUNT,"synthetic"),new IdentityRateLimiter.Subject(IdentityRateLimiter.Policy.LOGIN_IP,"192.0.2.10")));}
    @Test void missingAndZeroLimiterKeyFailConfiguration(){var ds=mock(javax.sql.DataSource.class);assertThrows(IllegalArgumentException.class,()->new JdbcIdentityRateLimiter(ds,null));assertThrows(IllegalArgumentException.class,()->new JdbcIdentityRateLimiter(ds,new byte[32]));assertThrows(IllegalArgumentException.class,()->new JdbcIdentityRateLimiter(ds,new byte[31]));}
    @Test void limiterIdentifiersAreDedicatedHmacAndPurposeSeparated(){var ds=mock(javax.sql.DataSource.class);byte[] key=new byte[32];Arrays.fill(key,(byte)42);var a=new JdbcIdentityRateLimiter(ds,key);var s=new IdentityRateLimiter.Subject(IdentityRateLimiter.Policy.LOGIN_ACCOUNT,"synthetic");assertArrayEquals(a.identifier(s),new JdbcIdentityRateLimiter(ds,key).identifier(s));assertFalse(Arrays.equals(a.identifier(s),a.identifier(new IdentityRateLimiter.Subject(IdentityRateLimiter.Policy.LOGIN_IP,"synthetic"))));Arrays.fill(key,(byte)43);assertFalse(Arrays.equals(a.identifier(s),new JdbcIdentityRateLimiter(ds,key).identifier(s)));assertFalse(s.toString().contains("synthetic"));}
    @Test void allSixPoliciesKeepExactApprovedLimits(){assertEquals(List.of(5,30,30,5,3,20),Arrays.stream(IdentityRateLimiter.Policy.values()).map(p->p.limit).toList());assertEquals(List.of(900,900,300,900,3600,3600),Arrays.stream(IdentityRateLimiter.Policy.values()).map(p->p.seconds).toList());}

    @Test void refreshStorageFailureIs503WithoutCredentialReplacement()throws Exception{when(sessions.refreshIdentity(any())).thenThrow(new IdentityRateLimiter.Unavailable());var s=run(request("refresh"));code(s,503,"SERVICE_UNAVAILABLE");assertTrue(s.getHeaders("Set-Cookie").isEmpty());assertFalse(s.getContentAsString().contains("accessToken"));}
}
